-- Removes the SalesDesk demo data. Generated by scripts/make-demo-seed.py.
-- Only the 2 sample projects, their customers and plots, the fake @example.com staff and demo campaigns.
-- Your own projects, customers and staff are not touched. Safe to run twice.
begin;
delete from public.meta_events where project_id in ('e0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002');
delete from public.leads where project_id in ('e0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002');
delete from public.projects where id in ('e0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002');
delete from public.campaigns where id in ('e2000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000002','e2000000-0000-4000-8000-000000000003','e2000000-0000-4000-8000-000000000004','e2000000-0000-4000-8000-000000000005');
delete from public.notifications where user_id in ('d0000000-0000-4000-8000-000000000001','d0000000-0000-4000-8000-000000000002','d0000000-0000-4000-8000-000000000003','d0000000-0000-4000-8000-000000000004','d0000000-0000-4000-8000-000000000005');
delete from auth.users where id in ('d0000000-0000-4000-8000-000000000001','d0000000-0000-4000-8000-000000000002','d0000000-0000-4000-8000-000000000003','d0000000-0000-4000-8000-000000000004','d0000000-0000-4000-8000-000000000005');
commit;
